45	function main(): void {
46	  const body = process.env.PR_BODY ?? "";
47	  const prNumber = (process.env.PR_NUMBER ?? "").trim();
48	  const repo = `${process.env.OWNER ?? ""}/${process.env.REPO ?? ""}`;
49	  const githubOutput = process.env.GITHUB_OUTPUT;
50	
51	  const say = (message: string): void => console.error(message);
52	  const write = (reinvoked: boolean): void => {
53	    if (githubOutput) appendFileSync(githubOutput, `reinvoked=${reinvoked}\n`);
54	  };
55	
56	  const parentIssue = PARENT_ISSUE_TAG.read(body);
57	  const originAgent = ORIGIN_AGENT_TAG.read(body);
58	  // Read, not assumed. A pull request body names its parent only when it was opened
59	  // from an issue run; a root pull request has none, and there is nobody to re-invoke.
60	  //
61	  // `readTargetState` with an explicit repo: this job runs in a checkout of the
62	  // MACHINERY, which may not be the repository the pull request is in. An unread state
63	  // is treated as NOT closed, so the judgement is preferred over silently aggregating.
64	  const parentState = parentIssue === undefined ? undefined : readTargetState(parentIssue, repo);
65	  const parentAlreadyClosed = parentState?.known === true && parentState.state !== "open";
66	
67	  const handoff = decidePostMergeHandoff({ parentIssue, parentAlreadyClosed, originAgent });
68	
69	  switch (handoff.kind) {
70	    case "no-parent":
71	      say(`PR #${prNumber} has no parent issue; nothing to re-invoke.`);
72	      write(false);
73	      return;
74	    case "already-closed":
75	      say(`Parent issue #${handoff.parentIssue} is already closed; nothing to re-invoke.`);
76	      write(false);
77	      return;
78	    case "close-directly":
79	      // No origin agent tagged. This is the fallback the aggregate job already is, so
80	      // it is left to run rather than duplicated here.
81	      say(`PR #${prNumber} has no origin agent tagged; the parent will be aggregated.`);
82	      write(false);
83	      return;
84	    case "reinvoke-origin-agent": {
85	      const dispatched = dispatchPostMergeAgent(repo, handoff.parentIssue, handoff.agent);
86	      if (dispatched) {
87	        say(`Re-invoked ${handoff.agent} on #${handoff.parentIssue} to judge the merge.`);
88	        write(true);
89	      } else {
90	        // The intended hand-off failed. Aggregate as the fallback, the same choice
91	        // `mergePr` makes when its dispatch returns false -- better than a silent wait.
92	        say(`Could not re-invoke ${handoff.agent} on #${handoff.parentIssue}; the parent will be aggregated.`);
93	        write(false);
94	      }
95	      return;
96	    }
97	  }
98	}
