1	/**
2	 * post-merge-reinvoke.test.ts — `reinvoke-origin-agent` waits on nothing it does not
3	 * read, and keeps the merge gate it must not lose with the wait.
4	 *
5	 * `reinvoke-origin-agent` reads the pull request body itself (`atomaton:parent-issue`,
6	 * `atomaton:origin-agent`) and uses nothing `resolve-parent` answers. Gating it on that
7	 * resolution meant a root issue -- which has no parent, so the answer is "" -- was never
8	 * re-invoked after its pull request merged: `Atomaton PR Merged` run 39274230329
9	 * succeeded with `reinvoke-origin-agent`, `notify-parent` and `aggregate-sub-issues`
10	 * all skipped (#203, observed on #206 / pull request #233).
11	 *
12	 * The merge gate is a separate question. It used to be inherited from `parse` through
13	 * `needs` -- GitHub skips a job whose needed job was skipped -- so dropping `needs`
14	 * dropped it too, and `pull_request_target: closed` fires for a close that merged
15	 * nothing. A closed-unmerged pull request would then post "the pull request for this
16	 * issue merged" on its issue and start a run on it.
17	 *
18	 * The other two still need the parent: one writes to it, the other aggregates into it.
19	 * That difference is the thing worth holding -- a job may be free of an answer only
20	 * when it does not use it.
21	 */
22	import { describe, expect, test } from "bun:test";
23	import { readFileSync } from "node:fs";
24	
25	interface Job {
26	  needs?: string | string[];
27	  if?: string;
28	}
29	
30	function jobs(): Record<string, Job> {
31	  const workflow = Bun.YAML.parse(readFileSync("dist/.github/workflows/atomaton-pr-merged.yml", "utf8")) as {
32	    jobs: Record<string, Job>;
33	  };
34	  return workflow.jobs;
35	}
36	
37	/** `needs` as a list, whichever shape the generator wrote. */
38	function needs(job: Job | undefined): string[] {
39	  return [job?.needs ?? []].flat();
40	}
41	
42	describe("post-merge re-invocation", () => {
43	  test("does not wait on the resolved parent, but still only runs for a merge", () => {
44	    const reinvoke = jobs()["reinvoke-origin-agent"];
45	    expect(reinvoke, "run `bun run synth` first").toBeDefined();
46	    expect(reinvoke?.if ?? "", "the decision belongs to dispatch_post_merge.ts").not.toContain("parent_issue");
47	    expect(needs(reinvoke), "it uses nothing that resolution answers").not.toContain("resolve-parent");
48	    expect(reinvoke?.if ?? "", "a close that merged nothing must not re-invoke anybody").toContain(
49	      "github.event.pull_request.merged == true",
50	    );
51	  });
52	
53	  test("the jobs that use the parent still wait for it", () => {
54	    const all = jobs();
55	    for (const name of ["notify-parent", "aggregate-sub-issues"]) {
56	      expect(needs(all[name]), `${name} needs the resolved parent`).toContain("resolve-parent");
