{"content":"#!/usr/bin/env bun
/**
 * dispatch_rejected.ts — return a pull request that was closed WITHOUT merging
 * to the agent that opened it, as a rejection.
 *
 * ## Why this exists as a job of its own
 *
 * `pull_request_target: closed` fires for a person's close as well as a
 * person's merge, and until #267 every job listening for it was gated on
 * `merged == true`: a close that merged nothing started nothing, and a rejected
 * pull request left its branch behind, its issue open, and nobody told. The
 * close is a person's decision, but whether it means "rejected" or "shipped
 * some other way" is not readable from the event — so this job returns it to
 * the origin agent and decides nothing itself. The machine closes nothing on
 * this path; the judgement is the agent's, the same as a review result's (#215).
 *
 * The linked issue comes from `parse` — which runs for BOTH outcomes of
 * `closed` now, and whose output the merge-side jobs share — the origin agent
 * from the pull request body, and the issue's state from GitHub: the close is
 * returned only when the issue is still open, because a closed issue is the
 * person saying it is finished. No origin agent tagged (a person's own pull
 * request) returns nothing too — no directive is written for a pull request no
 * run of ours opened. `decideRejectionHandoff` holds that branch list.
 *
 * ## What it does not write
 *
 * No `$GITHUB_OUTPUT`. The merge route reports `reinvoked=` so the aggregate
 * job can stand down; this route has no fallback to coordinate with. When the
 * dispatch does not go out the job FAILS (`exit 1`) instead — a silent close is
 * the defect #267 exists to remove, and a red job is the only way a close that
 * woke nobody is visible at all.
 *
 * Env: PR_BODY, PR_NUMBER, ISSUE_NUMBER, OWNER, REPO
 */

import { dispatchRejectedPrAgent } from "../../adapters/actions/dispatch-targets.ts";
import { ORIGIN_AGENT_TAG } from "../../adapters/github/tags.ts";
import { readTargetState } from "../../adapters/github/target-state.ts";
import { decideRejectionHandoff } from "../../domain/work/handoff.ts";
import { defineScript } from "./lib/script-ref.ts";

export const ref = defineScript(import.meta.url);

function main(): void {
  const body = process.env.PR_BODY ?? "";
  const prNumber = (process.env.PR_NUMBER ?? "").trim();
  const issueRaw = (process.env.ISSUE_NUMBER ?? "").trim();
  const repo = `${process.env.OWNER ?? ""}/${process.env.REPO ?? ""}`;

  const say = (message: string): void => console.error(message);

  // From `parse`, not read out of the body again: parse already read the tag
  // for the merge-side jobs, and a second reader of one tag is the shape this
  // repository keeps removing.
  const issueNumber = issueRaw === "" ? undefined : Number(issueRaw);
  // Read, not assumed (same as dispatch_post_merge.ts): an unread state is
  // treated as NOT closed, so the judgement is preferred over a silent
  // stand-down.
  const state = issueNumber === undefined ? undefined : readTargetState(issueNumber, repo);
  const issueAlreadyClosed = state?.known === true && state.state !== "open";
  const originAgent = ORIGIN_AGENT_TAG.read(body);

  const handoff = decideRejectionHandoff({
    parentIssue: issueNumber,
    parentAlreadyClosed: issueAlreadyClosed,
    originAgent,
  });

  switch (handoff.kind) {
    case "nothing":
      say(`PR #${prNumber} was closed without merging; nothing re-invoked (${handoff.why}).`);
      return;
    case "reinvoke-origin-agent": {
      const dispatched = dispatchRejectedPrAgent(repo, handoff.parentIssue, handoff.agent, Number(prNumber));
      if (dispatched) {
        say(`Re-invoked ${handoff.agent} on #${handoff.parentIssue} to judge the rejection.`);
        return;
      }
      // The merge route stands the aggregate job up when its dispatch fails;
      // this route has no fallback -- nothing here a failed dispatch could
      // land on except silence, and silence is what #267 is about. Fail the
      // job so the missed hand-off is visible.
      say(`Could not re-invoke ${handoff.agent} on #${handoff.parentIssue}; failing the job rather than ending silently.`);
      process.exit(1);
    }
  }
}

if (import.meta.main) main();
","path":"src/entrypoints/machinery/dispatch_rejected.ts"}

{"content":"import { describe, expect, test } from "bun:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { makeConfigDir, runWithFakeGh, scriptPath } from "./testing/harness.ts";

/**
 * `dispatch_rejected.ts` is the workflow half of the rejection hand-off (#267):
 * a pull request closed WITHOUT merging is returned to its origin agent, as a
 * judgement for it to make -- the machine closes nothing on this path. The
 * tests here pin the four answers of `decideRejectionHandoff` as the script
 * carries them, the shape of the directive (tagged for the model, carrying the
 * situation and not the verdict), and the one thing this route has that the
 * merge route does not: no fallback, so a dispatch that did not go out fails
 * the job instead of ending it silently.
 */
function run(body: string, rules: { match: string[]; stdout?: string; code?: number }[], issueNumber = "17") {
  const configDir = makeConfigDir({});
  try {
    return runWithFakeGh(scriptPath("dispatch_rejected.ts"), [], {
      cwd: configDir,
      rules,
      env: {
        PR_BODY: body,
        PR_NUMBER: "20",
        ISSUE_NUMBER: issueNumber,
        OWNER: "owner",
        REPO: "repo",
      },
    });
  } finally {
    rmSync(configDir, { recursive: true, force: true });
  }
}

const open = { match: ["api", "issues/"], stdout: JSON.stringify({ state: "open" }) };
const closed = { match: ["api", "issues/"], stdout: JSON.stringify({ state: "closed", state_reason: "completed" }) };

/** A PR body from an issue run: the two tags `create_pr` injects. */
const BODY = [
  "<!-- atomaton:parent-issue=17 -->",
  "<!-- atomaton:origin-agent=engineer -->",
].join("\n");

/** The argv of the `gh issue comment` call that posts the rejection directive. */
function directiveComment(ghCalls: string[][]): string[] | undefined {
  return ghCalls.find((c) => c[0] === "issue" && c[1] === "comment");
}

describe("dispatch_rejected.ts", () => {
  test("returns the close to the origin agent when the issue is still open", () => {
    const r = run(BODY, [
      // The trigger comment, then the dispatch. `dispatchRunner` posts its marker
      // (`--jq .id`), reads the thread to confirm it (`--paginate`), then dispatches.
      // The thread read must SHOW the marker id 555: that is the freshness probe, and
      // a read that omits it is refused as `unconfirmed`.
      //
      // The specific comment rules come BEFORE the state rule: the fake takes the
      // first match, and the state rule's `["api", "issues/"]` is a substring of every
      // comment path here.
      { match: ["api", "issues/17/comments", "POST"], stdout: "555" },
      { match: ["api", "issues/17/comments", "--paginate"], stdout: JSON.stringify([{ id: 555, body: "<!-- atomaton:dispatch=engineer -->", user: { type: "Bot" } }]) },
      { match: ["issue", "comment"] },
      { match: ["workflow", "run"] },
      open,
    ]);
    expect(r.status).toBe(0);

    // The directive is the first thing posted, and it is tagged for the model:
    // it is the first user message the re-invoked agent reads, so it must reach
    // it -- and it names the situation, not the verdict.
    const comment = directiveComment(r.ghCalls);
    expect(comment, "the rejection directive is posted before anything is dispatched").toBeDefined();
    const body = comment?.[comment.indexOf("--body") + 1] ?? "";
    expect(body).toContain("atomaton:llm-context=include");
    expect(body).toContain("closed without merging");
    expect(body).toContain("#20");

    const dispatch = r.ghCalls.find((c) => c[0] === "workflow" && c[1] === "run") ?? [];
    expect(dispatch.join(" ")).toContain("agent=engineer");
    expect(dispatch.join(" ")).toContain("type=issue");
    expect(dispatch.join(" ")).toContain("number=17");
    // The thread walk names nobody in this fixture, so the field is sent empty
    // -- the point is that notify travels with the dispatch, not who it is here.
    expect(dispatch.join(" ")).toContain("notify=");
  });

  test("dispatches nothing when posting the directive fails, and fails the job", () => {
    const r = run(BODY, [{ match: ["issue", "comment"], code: 1 }, open]);
    // No fallback exists on this side. The merge route stands the aggregate job
    // up; here a hand-off that did not happen must be visible, so the job goes
    // red rather than ending silently.
    expect(r.status).toBe(1);
    expect(r.ghCalls.some((c) => c[0] === "workflow")).toBe(false);
  });

  test("does nothing when the issue is already closed", () => {
    const r = run(BODY, [closed]);
    expect(r.status).toBe(0);
    // Not even the directive: an issue a person closed stays a person's.
    expect(directiveComment(r.ghCalls)).toBeUndefined();
    expect(r.ghCalls.some((c) => c[0] === "workflow")).toBe(false);
  });

  test("does nothing when no origin agent is tagged", () => {
    const r = run("<!-- atomaton:parent-issue=17 -->", [open]);
    expect(r.status).toBe(0);
    expect(directiveComment(r.ghCalls)).toBeUndefined();
    expect(r.ghCalls.some((c) => c[0] === "workflow")).toBe(false);
  });

  test("does nothing when the pull request has no linked issue at all", () => {
    const r = run("just a body with no tags", [{ match: ["api", "issues/"] }], "");
    expect(r.status).toBe(0);
    // The state read is skipped with it: there is no number to read.
    expect(r.ghCalls).toHaveLength(0);
  });
});
